/* FlashMed — Planejador de Estudos: tarefas, agenda semanal e geração de cronograma. */
const PLANNER_WEEK=[['Seg','Segunda-feira'],['Ter','Terça-feira'],['Qua','Quarta-feira'],['Qui','Quinta-feira'],['Sex','Sexta-feira'],['Sáb','Sábado'],['Dom','Domingo']];
function plannerWeeklyDefaults(p){
 const saved=Array.isArray(p.weeklyAvailability)?p.weeklyAvailability:[];
 return PLANNER_WEEK.map(([key,label])=>{const old=saved.find(x=>x.day===key)||{};return {day:key,label,minutes:Number.isFinite(Number(old.minutes))?Number(old.minutes):(key==='Sáb'||key==='Dom'?0:Number(p.minutesPerDay)||60),tasks:String(old.tasks||'')}})
}
const plannerWeekDays=[['seg','Segunda'],['ter','Terça'],['qua','Quarta'],['qui','Quinta'],['sex','Sexta'],['sab','Sábado'],['dom','Domingo']];
const plannerQuotes=[
 'Um passo pequeno também é progresso. ♡',
 'Você não precisa dar conta de tudo hoje; só precisa começar.',
 'Constância vale mais do que um dia perfeito.',
 'Seu futuro é construído nos pequenos blocos de hoje.',
 'Respire. Reorganize. Continue no seu ritmo.',
 'Aprender também é descansar e recomeçar.',
 'Você está construindo algo importante, um dia de cada vez.'
];
function plannerQuoteOfDay(){const d=new Date();const key=d.getFullYear()*372+(d.getMonth()+1)*31+d.getDate();return plannerQuotes[key%plannerQuotes.length]}
function plannerTodayItems(){const p=db.studyPlan||{};const today=new Date().toISOString().slice(0,10);return (Array.isArray(p.weekSchedule)?p.weekSchedule:[]).filter(x=>x.date===today)}

function plannerToggleSUSTopic(wi,ti,checked){
 db.studyPlan=db.studyPlan||{};db.studyPlan.susBaChecklist=db.studyPlan.susBaChecklist||{};db.studyPlan.susBaChecklist[wi+'-'+ti]=!!checked;const ok=save();const host=document.getElementById('plannerSUSChecklist');if(host)host.innerHTML=plannerSUSChecklistHtml();if(ok&&cloud)syncUp();
}


function studyPlannerView(){
 const p=db.studyPlan||{examName:'',examDate:'',minutesPerDay:60,topics:(db.subjects||[]).join(', '),days:'Seg, Ter, Qua, Qui, Sex'};
 const topics=String(p.topics||'').split(/[,;\\n]/).map(x=>x.trim()).filter(Boolean);
 const dueCards=(db.cards||[]).filter(due).length;
 const weak=typeof subjStats==='function'?subjStats().filter(x=>x.attempts&&x.acc<70).sort((a,b)=>a.acc-b.acc).slice(0,3).map(x=>x.x):[];
 const validDate=p.examDate&&/^\\d{4}-\\d{2}-\\d{2}$/.test(p.examDate);
 const daysLeft=validDate?Math.max(0,Math.ceil((new Date(p.examDate+'T12:00:00')-new Date(new Date().toDateString()))/86400000)):null;
 const av=p.weeklyAvailability||Object.fromEntries(plannerWeekDays.map(([k])=>[k,k==='sab'||k==='dom'?0:60]));
 const tasks=Array.isArray(p.weeklyTasks)?p.weeklyTasks:[];
 const week=Array.isArray(p.weekSchedule)?p.weekSchedule:[];
 return `<div class="fmPlannerPageLayout"><div class="fmPlannerMain"><div class="panel hero"><div class="row" style="align-items:center;gap:12px"><span style="font-size:30px">🗓️</span><div><h2 style="margin:0">Seu planejamento, no seu ritmo</h2><p style="margin:5px 0 0">Organize sua semana e deixe o FlashMed distribuir as tarefas dentro do tempo que você realmente tem.</p></div></div><div id="fmQuickReminders" class="fmQuickReminders" style="margin-top:12px"><div class="fmQuickHead"><span>🔔 Lembretes rápidos</span><span class="fmQuickDrag" title="Arraste para mover" aria-label="Arraste para mover">⠿ mover</span></div><p class="muted" style="margin:4px 0 10px">Seminários, provas e eventos importantes — com contagem regressiva.</p><form class="fmQuickForm" onsubmit="fmQuickReminderAdd(event)"><input id="fmQuickTitle" class="field" maxlength="120" placeholder="Ex.: Preparar seminário de GO" aria-label="Nome do lembrete" required><input id="fmQuickDate" class="field" type="date" aria-label="Data do evento" required><button class="btn" type="submit">＋ Adicionar</button></form><div id="fmQuickReminderList" class="fmQuickList"></div></div></div>
 
 <div style="margin-top:14px"><h3 style="margin:0 0 5px">Tarefas</h3><p class="muted">Cadastre uma tarefa pontual ou programe uma rotina nos dias que escolher, sem precisar definir horário.</p><div class="fmTaskComposer"><input id="spTaskTitle" class="field" placeholder="O que você precisa fazer?"><input id="spTaskDate" type="date" class="field" aria-label="Data da tarefa"><input id="spTaskTime" type="time" class="field" aria-label="Horário (opcional)"><label class="plannerTaskColorLabel">Categoria <select id="spTaskCategory" class="field" aria-label="Categoria do compromisso" style="margin:0;min-width:145px"><option value="viagem">✈️ Viagens</option><option value="casa">🏠 Atividades de casa</option><option value="atividade">🏃 Atividade física</option><option value="autocuidado">🌿 Autocuidado</option><option value="outros" selected>📌 Outros compromissos</option></select></label><label class="plannerTaskColorLabel">Duração (minutos) <input id="spTaskDuration" class="field" type="number" min="5" max="720" step="5" value="30" style="margin:0;width:110px"></label><select id="spTaskPriority" class="field" aria-label="Prioridade da tarefa"><option value="alta">🔴 Alta prioridade</option><option value="normal" selected>🟣 Prioridade normal</option><option value="baixa">🟢 Pode ser feito depois</option></select><label class="fmRecurringToggle"><input type="checkbox" id="spTaskRecurring" onchange="plannerToggleRecurringDays(this.checked)"> Repetir semanalmente</label><button class="btn" onclick="plannerAddStructuredTask()">＋ Adicionar tarefa</button></div><div id="spRecurringDays" class="fmRecurringDays" hidden><span>Escolha os dias:</span><label><input type="checkbox" name="spRecurringDay" value="1" checked>Seg</label><label><input type="checkbox" name="spRecurringDay" value="2" checked>Ter</label><label><input type="checkbox" name="spRecurringDay" value="3" checked>Qua</label><label><input type="checkbox" name="spRecurringDay" value="4" checked>Qui</label><label><input type="checkbox" name="spRecurringDay" value="5" checked>Sex</label><label><input type="checkbox" name="spRecurringDay" value="6" >Sáb</label><label><input type="checkbox" name="spRecurringDay" value="7" >Dom</label><small>As ocorrências serão criadas para os próximos 12 meses. Deixe o horário vazio se quiser apenas reservar o tempo, sem hora fixa.</small></div><div id="spTaskMessage" class="muted" style="margin-top:6px"></div><p class="muted">As tarefas ficam vinculadas ao cronograma semanal; use o cronograma abaixo para visualizar e ajustar a distribuição.</p><div id="spTaskList" class="fmTaskList" style="display:none">${plannerTaskListHtml()}</div></div>
 <div class="row" style="margin-top:12px"><button class="btn" onclick="saveWeeklyPlanner()">Salvar disponibilidade</button></div><p id="spWeeklyMessage" class="muted"></p></div>
 <div class="panel plannerWeeklyPanel" style="margin-top:14px"><h3>📅 Cronograma semanal</h3><p class="muted">Segunda a domingo, de hora em hora a partir das 5h30. Cores: estudos personalizáveis; compromissos fixos e pessoais aparecem em cores distintas.</p><div id="spWeeklySchedule">${plannerWeeklyScheduleHtml(week)}</div></div>
 <details class="panel" style="margin-top:14px"><summary style="cursor:pointer;font-weight:800">Configurações adicionais da prova e dos assuntos</summary><div style="margin-top:12px"><label>Nome da prova ou objetivo<input id="spExamName" class="field" maxlength="100" placeholder="Ex.: ENAMED, SUS-BA..." value="${esc(p.examName||'SUS-BA')}"></label><div class="row" style="margin-top:10px"><label style="flex:1;min-width:150px">Data da prova<input id="spExamDate" type="date" class="field" value="${esc(p.examDate||'2026-11-29')}"></label><label style="flex:1;min-width:150px">Minutos por dia (meta)<input id="spMinutes" type="number" class="field" min="15" max="600" step="15" value="${Number(p.minutesPerDay)||60}"></label></div><label style="display:block;margin-top:10px">Assuntos prioritários<textarea id="spTopics" class="field" rows="3" placeholder="Pediatria, Clínica Médica, Preventiva...">${esc(p.topics||'')}</textarea></label><button class="btn ghost" style="margin-top:10px" onclick="saveStudyPlan()">Salvar configurações</button><p id="spSaveMessage" class="muted"></p><div id="spGenerated">${plannerSessionsHtml(p)}</div></div></details></div><aside class="fmPlannerPriorityRail">${fmDashboardUpcomingHtml()}</aside></div>`;
}
function plannerImportGoCalendar(){
 const start=new Date(2026,9,12,12),end=new Date(2026,11,20,12),events=[];
 const key=d=>agendaDateKey(d);
 const add=(date,title,time='',duration=0,category='Internato GO',priority='normal')=>events.push({id:'go2026_'+date+'_'+title.toLowerCase().replace(/[^a-z0-9]+/g,'_').slice(0,42),title,date,time,duration,category,priority,createdAt:new Date().toISOString(),updatedAt:Date.now(),notes:'Escala de internato GO — Grupo 2'});
 const seminars=[
 ['2026-10-19','Seminário Obstetrícia: Hemorragia pós-parto'],
 ['2026-10-26','Seminário Obstetrícia: Diabetes gestacional'],
 ['2026-10-21','Seminário Ginecologia: Sangramento uterino anormal'],
 ['2026-10-28','Seminário Ginecologia: Métodos contraceptivos'],
 ['2026-11-02','Seminário Obstetrícia: Síndromes hipertensivas na gestação'],
 ['2026-11-04','Seminário Ginecologia: HPV e câncer do colo uterino'],
 ['2026-11-09','Seminário Obstetrícia: Rotura prematura de membranas e trabalho de parto prematuro'],
 ['2026-11-11','Seminário Ginecologia: Infecções sexualmente transmissíveis'],
 ['2026-11-16','Seminário Obstetrícia: Sangramento da primeira metade da gestação'],
 ['2026-11-18','Seminário Ginecologia: Climatério e TRH'],
 ['2026-11-23','Seminário Obstetrícia: Sangramento da segunda metade da gestação'],
 ['2026-11-25','Seminário Ginecologia: Endometriose — Larissa e Gabriela Souza'],
 ['2026-11-30','Seminário Obstetrícia: TORCH (sífilis, toxoplasmose e CMV)'],
 ['2026-12-02','Seminário Ginecologia: Massas anexiais e câncer de ovário'],
 ['2026-12-07','Seminário Obstetrícia: Isoimunização ABO/Rh'],
 ['2026-12-09','Seminário Ginecologia: Alterações funcionais benignas das mamas']
 ];
 for(const [date,title] of seminars)add(date,title,'',0,'Seminários GO','alta');
 add('2026-11-29','PROVA SUS-BA','',0,'Prova','alta');
 add('2026-12-17','Avaliação teórica GO — confirmar com os professores','',0,'Avaliação','alta');
 const exceptions={
 '2026-10-30':'Sem PNAR no ESAU — feriado do servidor',
 '2026-11-02':'Finados — sem PNAR no ESAU',
 '2026-11-06':'Sem PNAR com Maurício (viagem)',
 '2026-11-09':'Aniversário de Vitória da Conquista — sem PNAR no ESAU'
 };
 for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){
  const date=key(d),dow=d.getDay(),day=d.getDate(),month=d.getMonth()+1;
  if(dow===0||dow===6){add(date,'Jequié — plantão no HGPV / fim de semana','',0,'Plantão','alta');continue}
  if(exceptions[date])add(date,exceptions[date],'',0,'Dispensa / feriado','alta');
  if(date==='2026-11-29')continue;
  const period=date<='2026-11-01'?2:date<='2026-11-22'?3:date<='2026-12-06'?4:1;
  const put=(title,time,duration=300,cat='Internato GO')=>add(date,title,time,duration,cat);
  if(period===2){
   if(dow===1){put('CAAV — Renivaldo (manhã)','08:00');put('CAAV — Renivaldo (tarde)','13:00');put('Aula de Obstetrícia','19:00',120,'Aula')}
   if(dow===2){put('Patologia — Prof. Gabriel','08:00');put('Maria Rosa — Ademário','13:00');put('Radiologia — Prof. Zamilute','19:00',120,'Aula')}
   if(dow===3){if(date!=='2026-10-30')put('PNAR — Dra. Mayana (FSVC)','08:00');put('Maria Rosa — Ademário','13:00');put('Aula de Ginecologia','19:00',120,'Aula')}
   if(dow===4)put('Laboratório / Radiologia','13:00');
   if(dow===5&&date!=='2026-10-30'&&date!=='2026-11-06')put('PNAR — Maurício (FSVC)','13:00');
  }else if(period===3){
   if(dow===1){if(date!=='2026-11-02'&&date!=='2026-11-09')put('PNAR — Thaís (FSVC)','08:00');put('Ginecologia — Jacqueline (CAE 2)','13:00');if(date!=='2026-11-02')put('Aula de Obstetrícia','19:00',120,'Aula')}
   if(dow===2){put('Patologia — Prof. Gabriel','08:00');put('Radiologia — Prof. Zamilute + plantão Dra. Kessiane','19:00',120,'Aula')}
   if(dow===3)put('Aula de Ginecologia','19:00',120,'Aula');
   if(dow===4)put('Cirurgia ginecológica + ambulatório pré-operatório — Dr. André','08:00');
   if(dow===5&&[13,27].includes(day)) {put('Plantão equipe Mayanna (FSVC)','08:00');put('Plantão equipe Mayanna (FSVC)','13:00')}
  }else if(period===4){
   if(dow===1){put('Dra. Renata — GIN Lagoa das Flores','08:00');put('Dra. Renata Sobreira — GIN Lagoa das Flores','13:00');put('Aula de Obstetrícia','19:00',120,'Aula')}
   if(dow===2){put('Patologia — Prof. Gabriel','08:00');put('Radiologia — Prof. Zamilute','19:00',120,'Aula')}
   if(dow===3)put('Aula de Ginecologia','19:00',120,'Aula');
   if(dow===4){put('Plantão Dra. Daniela (FSVC)','08:00');put('Plantão Dra. Daniela (FSVC)','13:00')}
   if(dow===5)put('PNAR — Dr. André (FSVC)','08:00');
  }else{
   if(dow===1){put('Plantão Mayana (FSVC)','08:00');put('Plantão Mayana (FSVC)','13:00');put('Aula de Obstetrícia','19:00',120,'Aula')}
   if(dow===2){put('Patologia — Prof. Gabriel','08:00');put('Radiologia — Prof. Zamilute','19:00',120,'Aula')}
   if(dow===4)put('Ginecologia — Jacqueline (CAE 2)','13:00');
   if(dow===5){put('USG — Maurício (FSVC)','08:00');put('PNAR — Maurício (FSVC)','13:00')}
  }
 }
 const seen=new Set((db.agendaEvents||[]).map(e=>String(e.id)));
 const fresh=events.filter(e=>!seen.has(e.id));
 db.agendaEvents=db.agendaEvents||[];db.agendaEvents.push(...fresh);
 db.studyPlan=db.studyPlan||{};db.studyPlan.examName=db.studyPlan.examName||'SUS-BA';db.studyPlan.examDate=db.studyPlan.examDate||'2026-11-29';
 db.studyPlan.weeklyAvailability=db.studyPlan.weeklyAvailability||{seg:60,ter:60,qua:60,qui:60,sex:60,sab:0,dom:0};
 db.studyPlan.weeklyAvailability.sab=0;db.studyPlan.weeklyAvailability.dom=0;
 const ok=save();render();
 toast(ok?('Agenda GO importada: '+fresh.length+' novos eventos. Confira os feriados e a escala.'): 'Importação preparada, mas confira a sincronização.');
}
function plannerParseNaturalTask(raw){let title=String(raw||'').trim(),date='',minutes=30,time='';const dm=title.match(/\b(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})\b/);if(dm){let y=+dm[3];if(y<100)y+=2000;const d=new Date(y,+dm[2]-1,+dm[1],12);if(d.getFullYear()!==y||d.getMonth()!==+dm[2]-1||d.getDate()!==+dm[1])return {error:'Confira a data.'};date=agendaDateKey(d);title=title.replace(dm[0],' ')}const du=title.match(/\b(?:durante|por)\s+(\d{1,3})\s*(?:minutos|min)\b/i)||title.match(/\b(\d{1,3})\s*(?:minutos|min)\b/i);if(du){minutes=+du[1];if(minutes<15||minutes>720)return {error:'Use duração de 15 a 720 minutos.'};title=title.replace(du[0],' ')}const tm=title.match(/\b(?:às?\s*)?([01]?\d|2[0-3])(?:h|:([0-5]\d))\b/i);if(tm){time=String(+tm[1]).padStart(2,'0')+':'+(tm[2]||'00');title=title.replace(tm[0],' ')}title=title.replace(/[,;]+/g,' ').replace(/\s+/g,' ').trim();if(!title)return {error:'Escreva a tarefa.'};if(!date)return {error:'Inclua a data (DD/MM/AAAA).'};return {title,date,minutes,time,priority:'normal'}}
function plannerPriorityMeta(p){const map={alta:{label:'Alta prioridade',cls:'high'},normal:{label:'Prioridade normal',cls:'normal'},baixa:{label:'Pode ser feito depois',cls:'low'}};return map[p]||map.normal}
function plannerSetTaskPriority(id,value){if(!['alta','normal','baixa'].includes(value))return;const p=db.studyPlan||{},t=(p.weeklyTasks||[]).find(x=>String(x.id)===String(id)),stamp=Date.now();if(!t)return;t.priority=value;t.updatedAt=stamp;for(const item of p.weekSchedule||[])if(String(item.taskId||item.id)===String(id)){item.priority=value;item.updatedAt=stamp}for(const e of db.agendaEvents||[])if(String(e.studyTaskId||'')===String(id)){e.priority=value;e.updatedAt=stamp}p.updatedAt=stamp;save();render()}
function plannerTaskListHtml(){const ts=db.studyPlan?.weeklyTasks||[];return ts.length?ts.map(t=>{const pr=plannerPriorityMeta(t.priority);return '<div class="fmTaskItem priority-'+pr.cls+'"><div><b>'+esc(t.title)+'</b><small>'+esc(agendaFormatDate(t.date||'',{day:'2-digit',month:'short',year:'numeric'}))+' · '+(t.minutes||30)+' min · <span class="fmPriorityLabel">'+pr.label+'</span></small></div><div class="fmTaskActions"><select aria-label="Prioridade" onchange="plannerSetTaskPriority('+JSON.stringify(t.id).replace(/"/g,'&quot;')+',this.value)" class="fmPrioritySelect"><option value="alta" '+(t.priority==='alta'?'selected':'')+'>Alta</option><option value="normal" '+((!t.priority||t.priority==='normal')?'selected':'')+'>Normal</option><option value="baixa" '+(t.priority==='baixa'?'selected':'')+'>Depois</option></select><button onclick="plannerEditNaturalTask('+JSON.stringify(t.id).replace(/"/g,'&quot;')+')">Editar</button><button onclick="plannerDeleteNaturalTask('+JSON.stringify(t.id).replace(/"/g,'&quot;')+')">×</button></div></div>'}).join(''):'<p class="muted">Nenhuma tarefa cadastrada.</p>'}
function plannerToggleRecurringDays(show){const el=document.getElementById('spRecurringDays');if(el)el.hidden=!show;const date=document.getElementById('spTaskDate');if(date){date.required=!show;date.setAttribute('aria-label',show?'Data de início da rotina (opcional)':'Data da tarefa')}}
function plannerAddStructuredTask(){const title=(document.getElementById('spTaskTitle')?.value||'').trim(),dateInput=document.getElementById('spTaskDate')?.value||'',time=document.getElementById('spTaskTime')?.value||'',msg=document.getElementById('spTaskMessage'),recurring=!!document.getElementById('spTaskRecurring')?.checked,minutes=Number(document.getElementById('spTaskDuration')?.value||30);if(!title){if(msg)msg.textContent='Informe o nome da atividade.';return}if(!Number.isFinite(minutes)||minutes<5||minutes>720){if(msg)msg.textContent='A duração deve ser entre 5 e 720 minutos.';return}const startDate=dateInput||agendaDateKey(new Date());if(!recurring&&!dateInput){if(msg)msg.textContent='Escolha a data da tarefa.';return}const days=recurring?[...document.querySelectorAll('input[name="spRecurringDay"]:checked')].map(x=>Number(x.value)):[];if(recurring&&!days.length){if(msg)msg.textContent='Escolha pelo menos um dia da semana.';return}const p=db.studyPlan||(db.studyPlan={}),priority=document.getElementById('spTaskPriority')?.value||'normal',taskCategory=document.getElementById('spTaskCategory')?.value||'outros',color=plannerCategoryColor(taskCategory);if(!Array.isArray(p.weeklyTasks))p.weeklyTasks=[];if(!Array.isArray(p.weekSchedule))p.weekSchedule=[];if(!Array.isArray(db.agendaEvents))db.agendaEvents=[];const seriesId='routine_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7),base=new Date(startDate+'T12:00:00');if(recurring){let count=0;for(let w=0;w<53;w++){for(const weekday of days){const d=new Date(base);d.setDate(base.getDate()+w*7+((weekday-(base.getDay()||7)+7)%7));const date=agendaDateKey(d);if(date<startDate)continue;if(count>=days.length*53)break;const id=seriesId+'_'+date;p.weeklyTasks.push({id,seriesId,recurring:true,title,date,minutes,priority,color,taskCategory,done:false,time});p.weekSchedule.push({id:'ws_'+id,date,dateLabel:d.toLocaleDateString('pt-BR'),taskId:id,title,priority,color,taskCategory,minutes,startTime:time,endTime:'',done:false});db.agendaEvents.push({id:'agenda_'+id,studyTaskId:id,seriesId,recurring:true,title,date,time,duration:minutes,priority,color,taskCategory,category:'Rotina',done:false});count++}}if(msg)msg.textContent='Rotina adicionada aos dias escolhidos no cronograma pelos próximos 12 meses.'}else{const id='wt_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7);p.weeklyTasks.push({id,title,date:startDate,minutes,priority,color,taskCategory,done:false,time});p.weekSchedule.push({id:'ws_'+id,date:startDate,dateLabel:agendaDateFromKey(startDate)?.toLocaleDateString('pt-BR')||startDate,taskId:id,title,priority,color,taskCategory,minutes,startTime:time,endTime:'',done:false});db.agendaEvents.push({id:'agenda_'+id,studyTaskId:id,title,date:startDate,time,duration:minutes,priority,color,taskCategory,category:'Estudo'});if(msg)msg.textContent='Tarefa adicionada ao cronograma.'}save();render()}
function plannerAddNaturalTask(){const el=document.getElementById('spTaskQuick'),msg=document.getElementById('spTaskMessage'),v=plannerParseNaturalTask(el?.value||'');if(v.error){if(msg)msg.textContent=v.error;return}const p=db.studyPlan||(db.studyPlan={}),priority=document.getElementById('spTaskPriority')?.value||'normal',color=document.getElementById('spTaskColor')?.value||'#8b6bb1';if(!Array.isArray(p.weeklyTasks))p.weeklyTasks=[];const id='wt_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7);p.weeklyTasks.push({id,title:v.title,date:v.date,minutes:v.minutes,priority,color,done:false,time:v.time});if(!Array.isArray(db.agendaEvents))db.agendaEvents=[];db.agendaEvents.push({id:'ag_task_'+id,title:v.title,date:v.date,time:v.time||'',duration:v.minutes,category:'Estudos',priority,color,studyTaskId:id,createdAt:new Date().toISOString(),updatedAt:Date.now()});save();render()}
function plannerEditNaturalTask(id){const t=(db.studyPlan?.weeklyTasks||[]).find(x=>x.id===id);if(!t)return;const ans=prompt('Edite: tarefa, DD/MM/AAAA, durante 60 minutos',t.title+', '+t.date.split('-').reverse().join('/')+', durante '+t.minutes+' minutos');if(ans===null)return;const v=plannerParseNaturalTask(ans);if(v.error){alert(v.error);return}Object.assign(t,v,{updatedAt:Date.now()});const e=(db.agendaEvents||[]).find(x=>x.studyTaskId===id);if(e)Object.assign(e,{title:v.title,date:v.date,time:v.time||'',duration:v.minutes,priority:t.priority||'normal',color:t.color||e.color,updatedAt:Date.now()});save();render()}
async function plannerDeleteNaturalTask(id){const key=String(id);if(!confirm('Excluir esta tarefa e sua entrada na agenda?'))return;const p=db.studyPlan||(db.studyPlan={});const task=(p.weeklyTasks||[]).find(t=>String(t.id)===key);const slot=(p.weekSchedule||[]).find(t=>String(t.taskId||t.id)===key||String(t.id)===key);const event=(db.agendaEvents||[]).find(e=>String(e.studyTaskId||'')===key);const title=String(task?.title||slot?.title||event?.title||'').trim().toLocaleLowerCase('pt-BR');const date=String(task?.date||slot?.date||event?.date||'');p.weeklyTasks=(p.weeklyTasks||[]).filter(t=>String(t.id)!==key&&!(title&&String(t.title||'').trim().toLocaleLowerCase('pt-BR')===title&&String(t.date||'')===date));p.weekSchedule=(p.weekSchedule||[]).filter(t=>String(t.taskId||t.id)!==key&&String(t.id)!==key&&!(title&&String(t.title||'').trim().toLocaleLowerCase('pt-BR')===title&&String(t.date||'')===date));db.agendaEvents=(db.agendaEvents||[]).filter(e=>String(e.studyTaskId||'')!==key&&!(title&&String(e.title||'').trim().toLocaleLowerCase('pt-BR')===title&&String(e.date||'')===date));db.deletedWeeklyTaskIds=Array.isArray(db.deletedWeeklyTaskIds)?db.deletedWeeklyTaskIds:[];if(!db.deletedWeeklyTaskIds.map(String).includes(key))db.deletedWeeklyTaskIds.push(key);db.deletedWeeklyTaskKeys=Array.isArray(db.deletedWeeklyTaskKeys)?db.deletedWeeklyTaskKeys:[];const signature=title+'|'+date;if(title&&date&&!db.deletedWeeklyTaskKeys.includes(signature))db.deletedWeeklyTaskKeys.push(signature);p.updatedAt=Date.now();const ok=save();render();if(ok&&cloud){try{await syncUp();if(saveState)saveState.textContent='salvo na nuvem';toast('Tarefa excluída e sincronizada.')}catch(e){console.error('Falha ao sincronizar exclusão da tarefa',e);toast('A nuvem não confirmou a exclusão. Confira a conexão antes de atualizar.')}}else if(!ok)toast('Não foi possível confirmar o salvamento da exclusão.')}
function saveWeeklyPlanner(){
 const p=db.studyPlan||(db.studyPlan={}),availability={},startTimes={};
 for(const [k,label] of plannerWeekDays){const el=document.getElementById('spAvail_'+k),n=Number(el?.value||0);if(!Number.isFinite(n)||n<0||n>720){toast('Use de 0 a 720 minutos por dia.');return false}availability[k]=Math.round(n/15)*15;const st=document.getElementById('spStart_'+k)?.value||'05:30';if(!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(st)){toast('Confira o horário inicial de estudo.');return false}startTimes[k]=st}
 const taskInput=document.getElementById('spWeeklyTasks');let tasks=Array.isArray(p.weeklyTasks)?p.weeklyTasks:[];if(taskInput){const raw=taskInput.value||'';tasks=raw.split(/\\n|[\\r\\n]+/).map(x=>x.trim()).filter(Boolean).map((line,i)=>{const parts=line.split('|'),title=parts[0].trim(),n=Number((parts[1]||'').trim()),rawPriority=String(parts[2]||'normal').trim().toLowerCase(),priority=/^(alta|high|1)$/.test(rawPriority)?'alta':/^(baixa|low|3)$/.test(rawPriority)?'baixa':'normal',id='wt_'+i+'_'+title.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,24),prior=(p.weeklyTasks||[]).find(t=>t.id===id||t.title===title);return {id,title,minutes:Number.isFinite(n)&&n>0?Math.min(720,Math.round(n/15)*15):30,priority,done:!!prior?.done}})}
 p.weeklyAvailability=availability;p.weeklyStartTimes=startTimes;p.weeklyTasks=tasks;p.updatedAt=Date.now();const ok=save(),m=document.getElementById('spWeeklyMessage');if(m)m.textContent=ok?'Disponibilidade e tarefas salvas neste aparelho e enviadas para sincronização quando disponível.':'Não foi possível confirmar o salvamento.';toast(ok?'Semana salva ♡':'Confira o estado do salvamento');return !!ok;
}
function generateWeeklySchedule(){
 if(saveWeeklyPlanner()===false)return;const p=db.studyPlan||{},tasks=Array.isArray(p.weeklyTasks)?p.weeklyTasks:[],av=p.weeklyAvailability||{};
 if(!tasks.length){toast('Adicione ao menos uma tarefa para montar o cronograma.');return}
 const now=new Date(),monday=new Date(now);monday.setHours(12,0,0,0);monday.setDate(now.getDate()-((now.getDay()+6)%7));
 const prior=Array.isArray(p.weekSchedule)?p.weekSchedule:[],schedule=[],rank={urgente:0,alta:0,normal:1,depois:2,baixa:2},remaining=tasks.slice().sort((a,b)=>{const pa=rank[a.priority||'normal']??1,pb=rank[b.priority||'normal']??1;if(pa!==pb)return pa-pb;if(a.date&&b.date&&a.date!==b.date)return a.date.localeCompare(b.date);if(a.date&&!b.date)return -1;if(!a.date&&b.date)return 1;return 0}).map(t=>({...t,remaining:t.minutes})),startTimes=p.weeklyStartTimes||{};
 for(let d=0;d<7;d++){const date=new Date(monday);date.setDate(monday.getDate()+d);const dateKey=agendaDateKey(date),key=plannerWeekDays[d][0];let capacity=Number(av[key]||0),slot=0;const initial=startTimes[key]||'05:30';let cursor=Number(initial.slice(0,2))*60+Number(initial.slice(3,5)),guard=0;
  const busy=agendaEvents().filter(e=>e&&e.date===dateKey&&e.time&&Number(e.duration)>0).map(e=>({start:Number(e.time.slice(0,2))*60+Number(e.time.slice(3,5)),end:Number(e.time.slice(0,2))*60+Number(e.time.slice(3,5))+Number(e.duration)})).sort((a,b)=>a.start-b.start);
  while(capacity>0&&remaining.some(t=>t.remaining>0)&&slot<30&&guard++<120&&cursor<1440){let task=remaining.find(t=>t.remaining>0&&(!t.date||t.date===dateKey));if(!task)break;let chunk=Math.min(capacity,task.remaining,90);const occupied=busy.find(b=>cursor>=b.start&&cursor<b.end);if(occupied){cursor=occupied.end;continue}const nextBusy=busy.find(b=>b.start>cursor);if(nextBusy)chunk=Math.min(chunk,nextBusy.start-cursor);if(chunk<=0){cursor+=15;continue}const old=prior.find(x=>x.date===dateKey&&x.taskId===task.id&&x.done),startTime=String(Math.floor(cursor/60)).padStart(2,'0')+':'+String(cursor%60).padStart(2,'0');cursor+=chunk;const endTime=String(Math.floor(cursor/60)).padStart(2,'0')+':'+String(cursor%60).padStart(2,'0');schedule.push({id:'ws_'+dateKey+'_'+task.id+'_'+slot,date:dateKey,dateLabel:date.toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit'}),taskId:task.id,title:task.title,priority:task.priority||'normal',color:task.color||'#8b6bb1',minutes:chunk,startTime,endTime,done:!!old?.done});task.remaining-=chunk;capacity-=chunk;slot++}
 }
 const scheduledByTask={};schedule.forEach(x=>scheduledByTask[x.taskId]=(scheduledByTask[x.taskId]||0)+Number(x.minutes||0));const pending=tasks.map(t=>({...t,pendingMinutes:Math.max(0,Number(t.minutes||0)-Number(scheduledByTask[t.id]||0))})).filter(t=>t.pendingMinutes>0);p.weekSchedule=schedule;p.weekPendingTasks=pending.map(t=>{const item={id:t.id,title:t.title,date:t.date||'',minutes:t.pendingMinutes,priority:t.priority||'normal',reason:t.date&&t.date<agendaDateKey(monday)?'A data já passou':t.date&&t.date>agendaDateKey(new Date(monday.getTime()+6*86400000))?'A data está fora desta semana':'O tempo disponível não foi suficiente'};item.suggestion=plannerFindAlternativeSlot(item,p,monday,schedule);return item});p.updatedAt=Date.now();const ok=save();const out=document.getElementById('spWeeklySchedule');if(out)out.innerHTML=plannerWeeklyScheduleHtml(schedule)+plannerPendingTasksHtml(p.weekPendingTasks);const m=document.getElementById('spWeeklyMessage');if(m)m.textContent=p.weekPendingTasks.length?'Cronograma montado. '+p.weekPendingTasks.length+' tarefa(s) precisam de ajuste; nenhuma data foi alterada.':'Cronograma criado dentro dos limites informados.';toast(ok?'Cronograma semanal montado ♡':'Confira o estado do salvamento');
}
function plannerFindAlternativeSlot(task,p,weekStart,planned){const av=p.weeklyAvailability||{},starts=p.weeklyStartTimes||{},today=new Date();today.setHours(12,0,0,0);const todayKey=agendaDateKey(today);let earliest=task.date&&task.date>todayKey?task.date:todayKey;for(let offset=0;offset<21;offset++){const d=new Date(today);d.setDate(today.getDate()+offset);const dateKey=agendaDateKey(d);if(dateKey<earliest)continue;const k=plannerWeekDays[(d.getDay()+6)%7][0],available=Number(av[k]||0);if(!available||Number(task.minutes)>available)continue;let cursor=Number((starts[k]||'09:00').slice(0,2))*60+Number((starts[k]||'09:00').slice(3,5)),endLimit=Math.min(22*60,cursor+available),busy=agendaEvents().filter(e=>e&&e.date===dateKey&&e.time&&Number(e.duration)>0).map(e=>({start:Number(e.time.slice(0,2))*60+Number(e.time.slice(3,5)),end:Number(e.time.slice(0,2))*60+Number(e.time.slice(3,5))+Number(e.duration)}));(planned||[]).filter(x=>x.date===dateKey&&x.startTime&&Number(x.minutes)>0).forEach(x=>busy.push({start:Number(x.startTime.slice(0,2))*60+Number(x.startTime.slice(3,5)),end:Number(x.endTime.slice(0,2))*60+Number(x.endTime.slice(3,5))}));busy.sort((a,b)=>a.start-b.start);let guard=0;while(cursor+Number(task.minutes)<=endLimit&&guard++<80){const conflict=busy.find(b=>cursor<b.end&&cursor+Number(task.minutes)>b.start);if(!conflict)return {date:dateKey,time:String(Math.floor(cursor/60)).padStart(2,'0')+':'+String(cursor%60).padStart(2,'0'),minutes:Number(task.minutes)};cursor=Math.ceil(conflict.end/15)*15}}return null}
function plannerApproveAlternative(id){const p=db.studyPlan||{},pending=(p.weekPendingTasks||[]).find(x=>x.id===id),task=(p.weeklyTasks||[]).find(x=>x.id===id);if(!pending||!pending.suggestion||!task){toast('Sugestão não encontrada. Gere o cronograma novamente.');return}const s=pending.suggestion;task.date=s.date;task.time=s.time;const e=(db.agendaEvents||[]).find(x=>x.studyTaskId===id);if(e){e.date=s.date;e.time=s.time}p.weekPendingTasks=p.weekPendingTasks.filter(x=>x.id!==id);p.updatedAt=Date.now();const ok=save();if(ok){toast('Sugestão aprovada! Gere novamente o cronograma para reservar o horário.');render()}else toast('Não foi possível salvar a alteração.')}
function plannerPendingTasksHtml(items){if(!Array.isArray(items)||!items.length)return '';return '<section class="qbox plannerPending"><div class="row" style="align-items:center;gap:10px"><span class="plannerPendingIcon">!</span><div><h4 style="margin:0">Precisam de espaço no plano</h4><p class="muted" style="margin:3px 0 0">Sugestões de horário, sem alterações automáticas.</p></div></div><div class="plannerPendingList">'+items.map(t=>{const sug=t.suggestion;return '<div class="plannerPendingItem priority-'+(t.priority==='alta'?'high':t.priority==='baixa'?'low':'normal')+'"><div><b>'+esc(t.title)+'</b><small>'+Number(t.minutes||0)+' min pendentes · '+esc(t.reason||'Revisar data e disponibilidade')+'</small>'+(sug?'<small class="plannerSuggestion">Sugestão: '+esc(agendaFormatDate(sug.date,{weekday:'short',day:'2-digit',month:'2-digit'}))+' às '+esc(sug.time)+' · '+sug.minutes+' min</small>':'<small class="plannerSuggestion">Não encontrei um horário livre nos próximos 21 dias com a disponibilidade atual.</small>')+'</div>'+(sug?'<button class="btn secondary" onclick="plannerApproveAlternative('+JSON.stringify(t.id).replace(/"/g,'&quot;')+')">Aprovar</button>':'<button class="btn secondary" onclick="plannerReviewPending('+JSON.stringify(t.id).replace(/"/g,'&quot;')+')">Revisar data</button>')+'</div>'}).join('')+'</div></section>'}

function plannerReviewPending(id){const t=(db.studyPlan?.weeklyTasks||[]).find(x=>x.id===id);if(!t)return;const date=prompt('Esta tarefa ainda precisa de espaço. Informe uma nova data (DD/MM/AAAA) ou deixe em branco para manter a data atual:',t.date?agendaFormatDate(t.date,{day:'2-digit',month:'2-digit',year:'numeric'}):'');if(date===null)return;if(date.trim()){const m=date.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(!m){toast('Use o formato DD/MM/AAAA.');return}const d=new Date(Number(m[3]),Number(m[2])-1,Number(m[1]),12);if(d.getFullYear()!==Number(m[3])||d.getMonth()!==Number(m[2])-1||d.getDate()!==Number(m[1])){toast('Confira a data informada.');return}t.date=agendaDateKey(d);const e=(db.agendaEvents||[]).find(x=>x.studyTaskId===id);if(e)e.date=t.date}const ok=save();if(ok){toast('Tarefa atualizada. Gere o cronograma novamente para ver os horários.');render()}else toast('Não foi possível confirmar o salvamento.')}
function plannerDefaultWeekOffset(date=new Date()){return date.getDay()===0&&date.getHours()>=18?1:0}
let plannerWeekOffset=plannerDefaultWeekOffset(),plannerWeekManuallyNavigated=false,plannerAutoWeekSignature=plannerDefaultWeekOffset(),plannerScheduleMode='week',plannerDayKey=agendaDateKey(new Date());
function plannerSetScheduleMode(mode){plannerScheduleMode=mode==='day'?'day':'week';const el=document.getElementById('spWeeklySchedule');if(el)el.innerHTML=plannerWeeklyScheduleHtml((db.studyPlan||{}).weekSchedule||[])}
