function plannerSetStudyColor(id,color){const p=db.studyPlan||{},item=(p.weekSchedule||[]).find(x=>String(x.id)===String(id));if(!item||!/^#[0-9a-f]{6}$/i.test(color))return;const stamp=Date.now();item.color=color;item.updatedAt=stamp;const taskId=item.taskId;for(const part of p.weekSchedule||[])if(String(part.taskId)===String(taskId)){part.color=color;part.updatedAt=stamp}const task=(p.weeklyTasks||[]).find(x=>String(x.id)===String(taskId));if(task){task.color=color;task.updatedAt=stamp}const ev=(db.agendaEvents||[]).find(x=>String(x.studyTaskId)===String(taskId));if(ev){ev.color=color;ev.updatedAt=stamp}p.updatedAt=stamp;save();const el=document.getElementById('spWeeklySchedule');if(el)el.innerHTML=plannerWeeklyScheduleHtml(p.weekSchedule||[]);if(route==='Dashboard')render()}
